      'money.daily.villager.r3.item': 'Daily gold total',
      'money.daily.villager.r4.item': 'Extra rewards',
      'money.daily.villager.r4.detail': 'Wishing Stars + contribution medals (needed to raise DG level)',
      'money.daily.villager.r5.item': 'Quest types',
      'money.daily.villager.r5.detail': 'Deliver items, fish, gather, cook, building materials',
      'money.daily.villager.r6.item': 'Reset time',
      'money.daily.villager.r6.detail': 'Every day at 0:00 (game time)',
      'money.daily.tips.h3': '💡 Tips to maximize quest efficiency',
      'money.daily.tips.t1.h': 'Stockpile common items early',
      'money.daily.tips.t1.p': 'Keep in storage: 5-10 each of potatoes, wheat, blueberry jam, fish and chips, and vegetable medley. Hand them in the moment a quest arrives.',
      'money.daily.tips.t2.h': 'Take quests before heading out',
      'money.daily.tips.t2.p': 'Check what the 5 quests are each login, then head out and complete them in one trip — do not go back and forth.',
      'money.daily.tips.t3.h': 'Grow multiple crop types',
      'money.daily.tips.t3.p': 'Do not plant just one crop. Keep a few plots each of potatoes, tomatoes, carrots, and corn so you always have what a quest asks for.',
      'money.daily.tips.t4.h': 'Cooking quests = stacked profit',
      'money.daily.tips.t4.p': 'If a quest needs a cooked dish, make extra: hand in 1 for the quest + sell 4 more = quest reward + sale profit.',
      'money.daily.sources.h3': '💰 Daily gold source overview',
