      'prog.backpack.paid.r4.times': '&lt;strong&gt;Times 16+&lt;/strong&gt;',
      'prog.backpack.paid.r4.backpack': '+10 slots each',
      'prog.backpack.paid.r4.storage': '+50 slots each',
      'prog.backpack.paid.r4.price': 'Higher (increasing)',
      'prog.backpack.paid.r4.value': '⭐ Not recommended',
      'prog.backpack.paid.strategy': '&lt;strong&gt;🎯 Optimal strategy:&lt;/strong&gt; the first 5 backpack and first 5 warehouse expansions each cost only 10 stars. Buying both to 5 times each = &lt;strong&gt;100 Wishing Stars total = +50 backpack slots + 250 warehouse slots&lt;/strong&gt;. This is the single best Wishing Star spend in the whole game — bar none. From the 6th time it jumps to 25 stars, so stop there.',
      'prog.backpack.paid.budget': '&lt;strong&gt;💰 Wishing Star budget plan:&lt;/strong&gt; in the beginner phase (DG 1-7) save stars for the expansion discounts → first 5 backpack (50 stars) + first 5 warehouse (50 stars) = 100 stars → after buying out, save the rest for hobby tickets → at DG Lv.12+ if you\'re flush, consider the 6-10th expansions (25 stars each).',
      'prog.backpack.timeline.heading': '📅 Expansion Pacing Advice',
      'prog.backpack.timeline.th.phase': 'Phase',
      'prog.backpack.timeline.th.range': 'DG Range',
      'prog.backpack.timeline.th.action': 'Suggested Expansion Action',
