  // ---- Helpers ----
  function getStoredLang() {
    try {
      var l = localStorage.getItem(STORAGE_KEY);
      return (l === 'en' || l === 'zh') ? l : DEFAULT_LANG;
    } catch (e) { return DEFAULT_LANG; }
  }

  // Decode HTML entities in a translation value. Content agents emit their
  // English as HTML-escaped strings; decoding here makes them safe for BOTH
  // innerHTML (raw <strong> renders as a tag) and textContent/setAttribute
  // (raw & renders as "&" instead of the literal "&amp;").
  function dec(s) {
    if (typeof s !== 'string') return s;
    // Loop until stable: content agents emit English with entities escaped to
    // inconsistent depths (&lt;, &amp;lt;, even &amp;amp;lt;). Decoding repeatedly
    // normalizes every depth to the final characters, and is a no-op on already
    // decoded text (a literal "&" is never "&amp;").
    var prev;
    do {
      prev = s;
      s = s
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'");
    } while (s !== prev);
    return s;
  }

  function t(key, params) {
    var s = (dict[currentLang] && dict[currentLang][key]) || dict.en[key] || key;
    if (params) {
      for (var k in params) s = s.split('{' + k + '}').join(params[k]);
    }
    return dec(s);
  }

  // Translate a data-field value (enum token or free-text) to English.
  function L(value) {
    if (currentLang !== 'en') return value;
    if (value === null || value === undefined) return value;
    if (typeof value !== 'string') return value;
    var v = value.trim();
    if (!v) return value;
    if (dataEn[v]) return dec(dataEn[v]);
    // Tokenize "、" combinations: 春、秋 → Spring, Autumn
    if (v.indexOf('、') !== -1) {
      var parts = v.split('、');
      var all = true;
      for (var i = 0; i < parts.length; i++) {
        var p = parts[i].trim();
        if (!dataEn[p] && !patternValue(p)) { all = false; break; }
      }
      if (all) {
        return dec(parts.map(function (p) {
          var q = p.trim();
          return dataEn[q] || patternValue(q);
        }).join(', '));
      }
    }
    var pat = patternValue(v);
    if (pat) return dec(pat);
    return value;
  }

  // Programmatic pattern translations (level/unlock/reward families).
  function patternValue(v) {
    var m;
    m = v.match(/^烹饪等级(\d+)$/); if (m) return 'Cooking Lv.' + m[1];
    m = v.match(/^农耕等级(\d+)$/); if (m) return 'Farming Lv.' + m[1];
    m = v.match(/^采集等级(\d+)$/); if (m) return 'Foraging Lv.' + m[1];
    m = v.match(/^钓鱼Lv\.(\d+)$/); if (m) return 'Fishing Lv.' + m[1];
    m = v.match(/^观鸟Lv\.(\d+)$/); if (m) return 'Birdwatch Lv.' + m[1];
    m = v.match(/^音乐Lv\.(\d+)$/); if (m) return 'Music Lv.' + m[1];
    m = v.match(/^DG Lv\.(\d+)$/); if (m) return 'DG Lv.' + m[1];
    m = v.match(/^DG Lv\.(\d+)\/8\/11$/); if (m) return 'DG Lv.' + m[1] + '/8/11';
    m = v.match(/^许愿星 ×(\d+)$/); if (m) return 'Wishing Star ×' + m[1];
    m = v.match(/^(\d+)小时$/); if (m) return m[1] + 'h';
    m = v.match(/^(\d+(?:\.\d+)?)小时$/); if (m) return m[1] + 'h';
    return null;
  }

  function displayNameEn(nameEn) {
    if (!nameEn) return '';
    var s = String(nameEn).trim();
    if (!s) return '';
    s = s.replace(/-/g, ' ');
    s = s.replace(/([a-z0-9])([A-Z])/g, '$1 $2');
    s = s.replace(/\b[a-z]/g, function (c) { return c.toUpperCase(); });
    return s;
  }

  function nameFor(item) {
    if (!item) return '';
    if (currentLang === 'en') {
      return displayNameEn(item.nameEn) || item.name || '';
    }
    return item.name || '';
  }

  function getLang() { return currentLang; }
  function registerDataEn(map) {
    for (var k in map) dataEn[k] = map[k];
  }

  // ---- Chinese dictionary lazy-load (split out of the main bundle) ----
  // dict.zh lives in js/i18n-zh.js and is fetched only when the stored
  // language is Chinese or the user switches to Chinese, so English users
  // (the default) never download it.
  function registerZh(map) {
    dict.zh = map;
    zhLoaded = true;
    if (currentLang === 'zh') applyLanguage('zh');
  }

  function loadZh(onReady) {
    if (zhLoaded) { if (onReady) onReady(); return; }
    var s = document.createElement('script');
    s.src = 'js/i18n-zh.js';
    s.onload = function () { if (onReady) onReady(); };
    s.onerror = function () { if (onReady) onReady(); };
    document.head.appendChild(s);
  }

